---@class PlayerCommunityButton
local PlayerCommunityButton = Class('PlayerCommunityButton')
local UIModule = CS.Engine.UI.UIModule
local SDKService = import('Game.Entry.SDKService')
local KTool = CS.Engine.Lib.KTool
local cs_coroutine = require 'XLua.cs_coroutine'
function PlayerCommunityButton:__init()
    self.id = nil
    self.cardId = nil
    self.directPass = false --是否直接打开
    self.directPassUrl = "" --是否直接打开url
    self.co = nil   -- 发送携程请求
end
function PlayerCommunityButton:__delete()
    self.id = nil
    self.cardId = nil
    self.directPass = nil
    self.directPassUrl = nil
    self.co = nil
end

function PlayerCommunityButton:Awake()
    local SDKService = import('Game.Entry.SDKService')
    local sdkService = SDKService:GetInstance()
    local isEnabled = sdkService:IsSDKShowCommunity()
    KTool.SetActive(self.controller.gameObject, isEnabled);
end

function PlayerCommunityButton:SetCardId(cardId)
    self.cardId = cardId
end

function PlayerCommunityButton:SetDirectPassParam(directPass, directPassUrl)
    self.directPass = directPass
    self.directPassUrl = directPassUrl
end

function PlayerCommunityButton:SetJumpId(id)
    self.id = id
end

function PlayerCommunityButton:Start()
    KTool.SetActive(self.controller.gameObject, true);
    SetButtonAction(self.controller.gameObject ,Bind(self, self.ExecuteToggle) )
end

function PlayerCommunityButton:ExecuteToggle()
    local id = checkInt(self.id)
    if id > 0 then
        if id == 11 then
            xRecord.record('14-020', "click_comic")
        end
        local IdSettingId = AutoIds.IdSetting2510
        local tableId = tostring(id)
        local voName = 'CommunityJumpVo'
        if id == 2 then
            IdSettingId = AutoIds.IdSetting2509
            tableId = tostring(self.cardId)
            voName = 'CommunityCardJumpVo'
        end
        local jumpVo   = CfUtils.GetCfVo(IdSettingId, voName, tableId) or {}
        if not isNull(jumpVo) then
            ---@type UserComponent
            local userComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
            local userInfo =  userComp.userInfo
            local urlData  = {
                app_id       = userInfo.app_id,
                uid          = userInfo.openId,
                access_token = userInfo.access_token,
                callback     = jumpVo.gotoUrl or ''
            }
            local encodePar = ""
            if not self.directPass then
                encodePar = CS.UnityEngine.Networking.UnityWebRequest.EscapeURL(table.serialize(urlData))
            else
                encodePar = self.directPassUrl or ""
            end
            local urlAddress = string.format("%s%s", jumpVo.link or '', tostring(encodePar))
            if isNull(urlAddress) or string.len(urlAddress) == 0  then
                return
            end
            if id == 2 or checkInt(jumpVo.screen) == 0 then
                UIModule.OpenDialog({id = Constants.UITypeIds.CommunityDialog , parameters = urlAddress})
                return
            end
            if GameUtils.IsWindow() and id == 5 then
                CfUtils.OpenURL(urlAddress)
                return
            else
                SDKService:GetInstance():OpenCommnunity(urlAddress)
            end
            -- 记录社区的逻辑
            self:CommunityRecord()
        end
    end
end

function PlayerCommunityButton:CommunityRecord()
    local KCookie = CS.Engine.Lib.KCookie
    local isPreDownload = checkInt(KCookie.Get("IS_PRE_DOWNLOAD"))
    local url
    local data
    if isPreDownload == 1 then
        data = { targetId = 1 }
        url = "PrePlay/share"
    else
        data = { type = 1 }
        url = "player/shareTaskRecord"
    end
    local WWWEx = CS.Engine.Lib.Updater.WWWEx
    local wwwEx =  WWWEx.MakeWWWEx(url, data, "1eeba33bbdff3287f53af9b7bc209b5d", 3, 10);
    local HttpModule = CS.Engine.Http.HttpModule
    local UserId = HttpModule.RequestBodyMeta.UserId
    wwwEx:SetRequestHeader("Host", HttpModule.ServerHost)
    if not isNull(UserId) then
        UserId = tostring(UserId)
        local PlayerId =  tostring(HttpModule.RequestBodyMeta.PlayerId)
        wwwEx:SetRequestHeader("User-Agent", string.format("U:%s,P:%s",UserId,PlayerId))
    end
    -- 发送请求
    self.co = cs_coroutine.start(function()
        cs_coroutine.yield_return(wwwEx:LoadAsync(nil))
    end)
end

function PlayerCommunityButton:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    if self.co then
        -- 暂停携程
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    self:Delete()
end
return PlayerCommunityButton